//! SQL generated by the app: table browsing and staged grid edits. Identifiers are
//! always quoted; values are inlined as escaped literals, which every engine coerces
//! to the column type (same as typing them in its CLI).

use crate::adapters::dialect::Dialect;
use crate::domain::{
    AppError, BrowseRequest, Cell, ColumnDefinition, ColumnValue, Constraint, FilterOp, KeyValue,
    ReferentialAction, RowChange, SchemaChange, SortDirection,
};

fn table_ref(dialect: Dialect, schema: &str, table: &str) -> String {
    format!(
        "{}.{}",
        dialect.quote_ident(schema),
        dialect.quote_ident(table)
    )
}

/// Fetches `page_size + 1` rows so the caller knows whether a next page exists.
/// Without an explicit sort, orders by primary key so pages are stable.
/// One page of the table: the full query plus LIMIT/OFFSET (one extra row tells
/// whether there is a next page).
pub fn browse_sql(
    dialect: Dialect,
    request: &BrowseRequest,
    primary_key: &[String],
) -> Result<String, AppError> {
    let mut sql = select_sql(dialect, request, primary_key)?;
    let offset = u64::from(request.page) * u64::from(request.page_size);
    sql.push_str(&format!(" LIMIT {} OFFSET {offset}", request.page_size + 1));
    Ok(sql)
}

/// The table with the request's filters and order, every row (paging ignored).
pub fn select_sql(
    dialect: Dialect,
    request: &BrowseRequest,
    primary_key: &[String],
) -> Result<String, AppError> {
    let mut sql = format!(
        "SELECT * FROM {}",
        table_ref(dialect, &request.schema, &request.table)
    );

    let mut conditions = Vec::new();
    for filter in &request.filters {
        let column = dialect.quote_ident(&filter.column);
        let value = filter.value.as_deref().unwrap_or_default();
        let compare = |operator: &str| -> Result<String, AppError> {
            Ok(format!(
                "{column} {operator} {}",
                dialect.quote_literal(value)?
            ))
        };
        conditions.push(match filter.op {
            FilterOp::Eq => compare("=")?,
            FilterOp::Ne => compare("<>")?,
            FilterOp::Lt => compare("<")?,
            FilterOp::Lte => compare("<=")?,
            FilterOp::Gt => compare(">")?,
            FilterOp::Gte => compare(">=")?,
            FilterOp::Like => format!(
                "{} LIKE {}",
                dialect.text_cast(&column),
                dialect.quote_literal(value)?
            ),
            // ponytail: split on commas, so a value holding a comma cannot be listed; the SQL editor can
            FilterOp::In => {
                let items = in_items(value)
                    .map(|item| dialect.quote_literal(item))
                    .collect::<Result<Vec<_>, _>>()?;
                format!("{column} IN ({})", items.join(", "))
            }
            FilterOp::IsNull => format!("{column} IS NULL"),
            FilterOp::IsNotNull => format!("{column} IS NOT NULL"),
        });
    }
    if !conditions.is_empty() {
        sql.push_str(&format!(" WHERE {}", conditions.join(" AND ")));
    }

    let order: Vec<String> = match &request.sort {
        Some(sort) => {
            let direction = match sort.direction {
                SortDirection::Asc => "ASC",
                SortDirection::Desc => "DESC",
            };
            vec![format!("{} {direction}", dialect.quote_ident(&sort.column))]
        }
        None => primary_key.iter().map(|c| dialect.quote_ident(c)).collect(),
    };
    if !order.is_empty() {
        sql.push_str(&format!(" ORDER BY {}", order.join(", ")));
    }
    Ok(sql)
}

const SQLITE_ALTER: &str = "O SQLite não muda o tipo, o default nem o NULL de uma coluna \
     sem recriar a tabela: recrie-a pelo editor SQL";
const SQLITE_CONSTRAINT: &str = "O SQLite só declara constraints no CREATE TABLE: \
     adicionar ou remover uma exige recriar a tabela pelo editor SQL (UNIQUE: crie um índice UNIQUE)";
const MYSQL_MODIFY: &str =
    "No MySQL, tipo e NULL mudam redefinindo a coluna inteira (MODIFY COLUMN)";

/// The DDL statement of one structure change. Types, defaults and definitions are the
/// user's SQL, inlined as typed; names are quoted. Engine limits are errors that say
/// what the engine cannot do, not a silent rewrite.
pub fn schema_sql(
    dialect: Dialect,
    schema: &str,
    table: &str,
    change: &SchemaChange,
) -> Result<String, AppError> {
    let target = table_ref(dialect, schema, table);
    let q = |name: &str| dialect.quote_ident(name);
    let alter_column = |column: &str, action: &str| {
        format!("ALTER TABLE {target} ALTER COLUMN {} {action}", q(column))
    };
    let is_mysql = matches!(dialect, Dialect::Mysql { .. });
    let sql = match change {
        SchemaChange::CreateTable {
            columns,
            primary_key,
        } => {
            required(table, "o nome da tabela")?;
            if columns.is_empty() {
                return Err(AppError::validation(
                    "a tabela precisa de pelo menos uma coluna",
                ));
            }
            let mut lines = columns
                .iter()
                .map(|column| column_sql(dialect, column))
                .collect::<Result<Vec<_>, _>>()?;
            if let Some(missing) = primary_key
                .iter()
                .find(|key| !columns.iter().any(|column| &column.name == *key))
            {
                return Err(AppError::validation(format!(
                    "a chave primária usa {missing}, que não é uma coluna da tabela"
                )));
            }
            if !primary_key.is_empty() {
                lines.push(format!("PRIMARY KEY ({})", list(dialect, primary_key)));
            }
            format!("CREATE TABLE {target} (\n    {}\n)", lines.join(",\n    "))
        }
        SchemaChange::AddColumn { column } => {
            format!(
                "ALTER TABLE {target} ADD COLUMN {}",
                column_sql(dialect, column)?
            )
        }
        SchemaChange::RenameColumn { column, new_name } => {
            required(new_name, "o novo nome")?;
            format!(
                "ALTER TABLE {target} RENAME COLUMN {} TO {}",
                q(column),
                q(new_name)
            )
        }
        SchemaChange::DropColumn { column } => {
            format!("ALTER TABLE {target} DROP COLUMN {}", q(column))
        }
        SchemaChange::SetType {
            column,
            data_type,
            using,
        } => match dialect {
            Dialect::Postgres => {
                let mut action = format!("TYPE {}", required(data_type, "o tipo")?);
                if let Some(using) = using.as_deref().map(str::trim).filter(|u| !u.is_empty()) {
                    action.push_str(&format!(" USING {using}"));
                }
                alter_column(column, &action)
            }
            Dialect::Mysql { .. } => return Err(AppError::validation(MYSQL_MODIFY)),
            Dialect::Sqlite => return Err(AppError::validation(SQLITE_ALTER)),
        },
        SchemaChange::SetDefault { column, default } => {
            if dialect == Dialect::Sqlite {
                return Err(AppError::validation(SQLITE_ALTER));
            }
            match default.as_deref().map(str::trim).filter(|d| !d.is_empty()) {
                Some(default) => alter_column(column, &format!("SET DEFAULT {default}")),
                None => alter_column(column, "DROP DEFAULT"),
            }
        }
        SchemaChange::SetNullable { column, nullable } => match dialect {
            Dialect::Postgres => alter_column(
                column,
                if *nullable {
                    "DROP NOT NULL"
                } else {
                    "SET NOT NULL"
                },
            ),
            Dialect::Mysql { .. } => return Err(AppError::validation(MYSQL_MODIFY)),
            Dialect::Sqlite => return Err(AppError::validation(SQLITE_ALTER)),
        },
        SchemaChange::RedefineColumn { column, definition } => {
            if !is_mysql {
                return Err(AppError::validation(
                    "redefinir a coluna inteira (MODIFY COLUMN) é só do MySQL",
                ));
            }
            format!(
                "ALTER TABLE {target} MODIFY COLUMN {} {}",
                q(column),
                required(definition, "a definição")?
            )
        }
        SchemaChange::CreateIndex {
            name,
            columns,
            unique,
        } => {
            required(name, "o nome do índice")?;
            if columns.is_empty() {
                return Err(AppError::validation("escolha as colunas do índice"));
            }
            let unique = if *unique { "UNIQUE " } else { "" };
            let columns = list(dialect, columns);
            match dialect {
                // the index lives in the table's schema: SQLite names it there, not the table
                Dialect::Sqlite => format!(
                    "CREATE {unique}INDEX {} ON {} ({columns})",
                    table_ref(dialect, schema, name),
                    q(table)
                ),
                _ => format!("CREATE {unique}INDEX {} ON {target} ({columns})", q(name)),
            }
        }
        SchemaChange::DropIndex { name } => match dialect {
            Dialect::Mysql { .. } => format!("DROP INDEX {} ON {target}", q(name)),
            Dialect::Postgres | Dialect::Sqlite => {
                format!("DROP INDEX {}", table_ref(dialect, schema, name))
            }
        },
        SchemaChange::RenameIndex { name, new_name } => {
            required(new_name, "o novo nome")?;
            match dialect {
                Dialect::Postgres => format!(
                    "ALTER INDEX {} RENAME TO {}",
                    table_ref(dialect, schema, name),
                    q(new_name)
                ),
                Dialect::Mysql { .. } => format!(
                    "ALTER TABLE {target} RENAME INDEX {} TO {}",
                    q(name),
                    q(new_name)
                ),
                Dialect::Sqlite => {
                    return Err(AppError::validation(
                        "O SQLite não renomeia índices: remova e crie de novo com o novo nome",
                    ));
                }
            }
        }
        SchemaChange::RenameTable { new_name } => {
            required(new_name, "o novo nome")?;
            // MySQL would move a bare name to the session's database: keep it in this one
            let renamed = if is_mysql {
                table_ref(dialect, schema, new_name)
            } else {
                q(new_name)
            };
            format!("ALTER TABLE {target} RENAME TO {renamed}")
        }
        SchemaChange::DropTable => format!("DROP TABLE {target}"),
        SchemaChange::AddConstraint { name, constraint } => {
            if dialect == Dialect::Sqlite {
                return Err(AppError::validation(SQLITE_CONSTRAINT));
            }
            required(name, "o nome da constraint")?;
            let definition = match constraint {
                Constraint::Unique { columns } => {
                    if columns.is_empty() {
                        return Err(AppError::validation("escolha as colunas da constraint"));
                    }
                    format!("UNIQUE ({})", list(dialect, columns))
                }
                Constraint::Check { expression } => {
                    format!("CHECK ({})", required(expression, "a expressão do CHECK")?)
                }
                Constraint::ForeignKey {
                    columns,
                    referenced_table,
                    referenced_columns,
                    on_delete,
                } => {
                    required(referenced_table, "a tabela referenciada")?;
                    if columns.is_empty() || columns.len() != referenced_columns.len() {
                        return Err(AppError::validation(
                            "a chave estrangeira liga o mesmo número de colunas dos dois lados",
                        ));
                    }
                    let mut definition = format!(
                        "FOREIGN KEY ({}) REFERENCES {} ({})",
                        list(dialect, columns),
                        table_ref(dialect, schema, referenced_table),
                        list(dialect, referenced_columns)
                    );
                    if let Some(action) = on_delete {
                        definition.push_str(match action {
                            ReferentialAction::Restrict => " ON DELETE RESTRICT",
                            ReferentialAction::Cascade => " ON DELETE CASCADE",
                            ReferentialAction::SetNull => " ON DELETE SET NULL",
                        });
                    }
                    definition
                }
            };
            format!(
                "ALTER TABLE {target} ADD CONSTRAINT {} {definition}",
                q(name)
            )
        }
        // MySQL takes the generic form from 8.0.19 (FOREIGN KEY, CHECK, UNIQUE alike)
        SchemaChange::DropConstraint { name } => {
            if dialect == Dialect::Sqlite {
                return Err(AppError::validation(SQLITE_CONSTRAINT));
            }
            format!("ALTER TABLE {target} DROP CONSTRAINT {}", q(name))
        }
    };
    // a type or default typed with a `;` would smuggle in a second command
    if dialect.split(&sql).len() != 1 {
        return Err(AppError::validation(
            "a alteração gera mais de um comando: tipo, default e definição não podem ter `;`",
        ));
    }
    Ok(sql)
}

fn column_sql(dialect: Dialect, column: &ColumnDefinition) -> Result<String, AppError> {
    required(&column.name, "o nome da coluna")?;
    let mut sql = format!(
        "{} {}",
        dialect.quote_ident(&column.name),
        required(&column.data_type, &format!("o tipo de {}", column.name))?
    );
    if let Some(default) = column
        .default
        .as_deref()
        .map(str::trim)
        .filter(|d| !d.is_empty())
    {
        sql.push_str(&format!(" DEFAULT {default}"));
    }
    if !column.nullable {
        sql.push_str(" NOT NULL");
    }
    Ok(sql)
}

fn list(dialect: Dialect, names: &[String]) -> String {
    names
        .iter()
        .map(|name| dialect.quote_ident(name))
        .collect::<Vec<_>>()
        .join(", ")
}

fn required<'a>(value: &'a str, what: &str) -> Result<&'a str, AppError> {
    let value = value.trim();
    if value.is_empty() {
        return Err(AppError::validation(format!("informe {what}")));
    }
    Ok(value)
}

/// The values of an IN filter: comma-separated, trimmed, blanks dropped.
pub fn in_items(value: &str) -> impl Iterator<Item = &str> {
    value
        .split(',')
        .map(str::trim)
        .filter(|item| !item.is_empty())
}

/// One staged change. Rows are identified by their full primary key.
pub fn change_sql(
    dialect: Dialect,
    schema: &str,
    table: &str,
    change: &RowChange,
) -> Result<String, AppError> {
    let target = table_ref(dialect, schema, table);
    match change {
        RowChange::Update { key, values } => {
            if values.is_empty() {
                return Err(AppError::validation("alteração sem colunas"));
            }
            let assignments = values
                .iter()
                .map(|v| {
                    Ok(format!(
                        "{} = {}",
                        dialect.quote_ident(&v.column),
                        value_literal(dialect, v)?
                    ))
                })
                .collect::<Result<Vec<_>, AppError>>()?;
            Ok(format!(
                "UPDATE {target} SET {} WHERE {}",
                assignments.join(", "),
                key_condition(dialect, key)?
            ))
        }
        RowChange::Insert { values } if values.is_empty() => Ok(match dialect {
            // MySQL has no DEFAULT VALUES
            Dialect::Mysql { .. } => format!("INSERT INTO {target} () VALUES ()"),
            Dialect::Postgres | Dialect::Sqlite => format!("INSERT INTO {target} DEFAULT VALUES"),
        }),
        RowChange::Insert { values } => {
            let columns: Vec<String> = values
                .iter()
                .map(|v| dialect.quote_ident(&v.column))
                .collect();
            let literals = values
                .iter()
                .map(|v| value_literal(dialect, v))
                .collect::<Result<Vec<_>, AppError>>()?;
            Ok(format!(
                "INSERT INTO {target} ({}) VALUES ({})",
                columns.join(", "),
                literals.join(", ")
            ))
        }
        RowChange::Delete { key } => Ok(format!(
            "DELETE FROM {target} WHERE {}",
            key_condition(dialect, key)?
        )),
    }
}

fn value_literal(dialect: Dialect, value: &ColumnValue) -> Result<String, AppError> {
    match &value.value {
        Some(text) => dialect.quote_literal(text),
        None => Ok("NULL".to_string()),
    }
}

fn key_condition(dialect: Dialect, key: &[KeyValue]) -> Result<String, AppError> {
    if key.is_empty() {
        return Err(AppError::validation("linha sem chave primária"));
    }
    let conditions = key
        .iter()
        .map(|k| {
            Ok(format!(
                "{} = {}",
                dialect.quote_ident(&k.column),
                dialect.quote_literal(&key_text(&k.value)?)?
            ))
        })
        .collect::<Result<Vec<_>, AppError>>()?;
    Ok(conditions.join(" AND "))
}

fn key_text(cell: &Cell) -> Result<String, AppError> {
    match cell {
        Cell::Null => Err(AppError::validation("chave primária nula")),
        cell => exact_text(cell).ok_or_else(|| {
            AppError::validation("chave primária de um tipo que não pode ser editado")
        }),
    }
}

/// The exact text the engine rendered for a value. None for NULL and for what the grid
/// only carries in part: binary (a preview), arrays and unmodelled types.
fn exact_text(cell: &Cell) -> Option<String> {
    match cell {
        Cell::Bool(value) => Some(value.to_string()),
        // Rust prints the shortest text that round-trips, as the engines do
        Cell::Float(value) => Some(value.to_string()),
        Cell::Int(text)
        | Cell::Decimal(text)
        | Cell::Text(text)
        | Cell::Date(text)
        | Cell::Json(text) => Some(text.clone()),
        Cell::Timestamp { value, .. } => Some(value.clone()),
        Cell::Null | Cell::Bytes { .. } | Cell::Array(_) | Cell::Unknown { .. } => None,
    }
}

/// Rows as INSERT statements, one per row, with the same literals the grid edits use.
/// A value the grid only shows in part is refused rather than copied with loss.
pub fn insert_sql(
    dialect: Dialect,
    schema: &str,
    table: &str,
    columns: &[String],
    rows: &[Vec<Cell>],
) -> Result<String, AppError> {
    let statements = rows
        .iter()
        .map(|row| {
            if row.len() != columns.len() {
                return Err(AppError::validation(
                    "linha com número de colunas diferente",
                ));
            }
            let values = columns
                .iter()
                .zip(row)
                .map(|(column, cell)| {
                    let value = match cell {
                        Cell::Null => None,
                        cell => Some(exact_text(cell).ok_or_else(|| {
                            AppError::validation(format!(
                                "a coluna {column} tem um valor que a grade só mostra em parte \
                                 (binário, array ou tipo não modelado): copiar como INSERT \
                                 perderia dados"
                            ))
                        })?),
                    };
                    Ok(ColumnValue {
                        column: column.clone(),
                        value,
                    })
                })
                .collect::<Result<Vec<_>, AppError>>()?;
            change_sql(dialect, schema, table, &RowChange::Insert { values })
        })
        .collect::<Result<Vec<_>, AppError>>()?;
    Ok(statements
        .iter()
        .map(|statement| format!("{statement};\n"))
        .collect())
}

/// One INSERT for many rows (`None` is NULL), with the literals the grid edits use.
pub fn insert_rows_sql(
    dialect: Dialect,
    schema: &str,
    table: &str,
    columns: &[String],
    rows: &[Vec<Option<String>>],
) -> Result<String, AppError> {
    let names: Vec<String> = columns.iter().map(|c| dialect.quote_ident(c)).collect();
    let rows = rows
        .iter()
        .map(|row| Ok(format!("({})", row_literals(dialect, row)?.join(", "))))
        .collect::<Result<Vec<_>, AppError>>()?;
    Ok(format!(
        "INSERT INTO {} ({}) VALUES {}",
        table_ref(dialect, schema, table),
        names.join(", "),
        rows.join(", ")
    ))
}

/// Which value of a one-row `insert_rows_sql` statement holds `position`, the
/// 1-based character offset PostgreSQL reports for a value it cannot convert.
pub fn value_at(
    dialect: Dialect,
    statement: &str,
    row: &[Option<String>],
    position: usize,
) -> Option<usize> {
    let lengths: Vec<usize> = row_literals(dialect, row)
        .ok()?
        .iter()
        .map(|literal| literal.chars().count())
        .collect();
    // the statement ends with `(literal, literal)`
    let values = lengths.iter().sum::<usize>() + 2 * lengths.len().saturating_sub(1);
    let mut start = statement.chars().count().checked_sub(values)?;
    for (index, length) in lengths.into_iter().enumerate() {
        if (start..start + length).contains(&position) {
            return Some(index);
        }
        start += length + 2;
    }
    None
}

fn row_literals(dialect: Dialect, row: &[Option<String>]) -> Result<Vec<String>, AppError> {
    row.iter()
        .map(|value| match value {
            Some(text) => dialect.quote_literal(text),
            None => Ok("NULL".to_string()),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::{Filter, Sort};

    #[test]
    fn inserts_many_rows_and_finds_a_value_by_position() {
        let columns = vec!["id".to_string(), "name".to_string()];
        let rows = vec![
            vec![Some("1".to_string()), Some(r"c:\temp".to_string())],
            vec![Some("2".to_string()), None],
        ];
        assert_eq!(
            insert_rows_sql(Dialect::Postgres, "app", "users", &columns, &rows).unwrap(),
            r#"INSERT INTO "app"."users" ("id", "name") VALUES ('1', E'c:\\temp'), ('2', NULL)"#
        );
        assert_eq!(
            insert_rows_sql(MYSQL, "app", "users", &columns, &rows[1..]).unwrap(),
            "INSERT INTO `app`.`users` (`id`, `name`) VALUES ('2', NULL)"
        );

        // 1-based, in characters: "ç" is one
        let row = vec![Some("ç".to_string()), Some("x".to_string())];
        let one = insert_rows_sql(
            Dialect::Postgres,
            "s",
            "t",
            &columns,
            std::slice::from_ref(&row),
        )
        .unwrap();
        let first = one
            .find("'ç'")
            .map(|byte| one[..byte].chars().count() + 1)
            .unwrap();
        assert_eq!(value_at(Dialect::Postgres, &one, &row, first), Some(0));
        assert_eq!(value_at(Dialect::Postgres, &one, &row, first + 2), Some(0));
        assert_eq!(value_at(Dialect::Postgres, &one, &row, first + 3), None);
        assert_eq!(value_at(Dialect::Postgres, &one, &row, first + 5), Some(1));
        assert_eq!(value_at(Dialect::Postgres, &one, &row, 1), None);
    }

    const MYSQL: Dialect = Dialect::Mysql {
        backslash_escapes: true,
    };

    fn request() -> BrowseRequest {
        BrowseRequest {
            schema: "public".into(),
            table: "users".into(),
            filters: vec![],
            sort: None,
            page: 0,
            page_size: 100,
        }
    }

    fn key(column: &str, value: Cell) -> KeyValue {
        KeyValue {
            column: column.into(),
            value,
        }
    }

    fn value(column: &str, value: Option<&str>) -> ColumnValue {
        ColumnValue {
            column: column.into(),
            value: value.map(str::to_string),
        }
    }

    #[test]
    fn schema_changes_per_dialect() {
        use crate::domain::{ColumnDefinition, Constraint, ReferentialAction, SchemaChange as C};
        let column =
            |name: &str, data_type: &str, nullable: bool, default: Option<&str>| ColumnDefinition {
                name: name.into(),
                data_type: data_type.into(),
                nullable,
                default: default.map(str::to_string),
            };
        let sql = |dialect: Dialect, change: C| schema_sql(dialect, "app", "t", &change);
        let create = C::CreateTable {
            columns: vec![
                column("id", "bigint", false, None),
                column("we\"ird", "text", true, Some(" 'x' ")),
            ],
            primary_key: vec!["id".into()],
        };
        assert_eq!(
            sql(Dialect::Postgres, create.clone()).unwrap(),
            "CREATE TABLE \"app\".\"t\" (\n    \"id\" bigint NOT NULL,\n    \"we\"\"ird\" text DEFAULT 'x',\n    PRIMARY KEY (\"id\")\n)"
        );
        assert!(
            sql(MYSQL, create)
                .unwrap()
                .starts_with("CREATE TABLE `app`.`t` (\n    `id` bigint NOT NULL,")
        );

        let rename = || C::RenameColumn {
            column: "a".into(),
            new_name: "b".into(),
        };
        assert_eq!(
            sql(MYSQL, rename()).unwrap(),
            "ALTER TABLE `app`.`t` RENAME COLUMN `a` TO `b`"
        );
        assert_eq!(
            sql(
                Dialect::Sqlite,
                C::AddColumn {
                    column: column("c", "integer", false, Some("0"))
                }
            )
            .unwrap(),
            r#"ALTER TABLE "app"."t" ADD COLUMN "c" integer DEFAULT 0 NOT NULL"#
        );
        assert_eq!(
            sql(Dialect::Postgres, C::DropColumn { column: "c".into() }).unwrap(),
            r#"ALTER TABLE "app"."t" DROP COLUMN "c""#
        );

        // Postgres alters one attribute at a time
        let set_type = || C::SetType {
            column: "c".into(),
            data_type: "integer".into(),
            using: Some("c::integer".into()),
        };
        assert_eq!(
            sql(Dialect::Postgres, set_type()).unwrap(),
            r#"ALTER TABLE "app"."t" ALTER COLUMN "c" TYPE integer USING c::integer"#
        );
        let nullable = |nullable| C::SetNullable {
            column: "c".into(),
            nullable,
        };
        assert_eq!(
            sql(Dialect::Postgres, nullable(false)).unwrap(),
            r#"ALTER TABLE "app"."t" ALTER COLUMN "c" SET NOT NULL"#
        );
        assert_eq!(
            sql(Dialect::Postgres, nullable(true)).unwrap(),
            r#"ALTER TABLE "app"."t" ALTER COLUMN "c" DROP NOT NULL"#
        );
        let default = |value: Option<&str>| C::SetDefault {
            column: "c".into(),
            default: value.map(str::to_string),
        };
        assert_eq!(
            sql(MYSQL, default(Some("(now())"))).unwrap(),
            "ALTER TABLE `app`.`t` ALTER COLUMN `c` SET DEFAULT (now())"
        );
        assert_eq!(
            sql(Dialect::Postgres, default(Some("  "))).unwrap(),
            r#"ALTER TABLE "app"."t" ALTER COLUMN "c" DROP DEFAULT"#
        );
        // MySQL rewrites the whole column
        let redefine = || C::RedefineColumn {
            column: "c".into(),
            definition: "varchar(20) NOT NULL COMMENT 'x'".into(),
        };
        assert_eq!(
            sql(MYSQL, redefine()).unwrap(),
            "ALTER TABLE `app`.`t` MODIFY COLUMN `c` varchar(20) NOT NULL COMMENT 'x'"
        );

        let index = || C::CreateIndex {
            name: "t_ab".into(),
            columns: vec!["a".into(), "b".into()],
            unique: true,
        };
        assert_eq!(
            sql(Dialect::Postgres, index()).unwrap(),
            r#"CREATE UNIQUE INDEX "t_ab" ON "app"."t" ("a", "b")"#
        );
        assert_eq!(
            sql(Dialect::Sqlite, index()).unwrap(),
            r#"CREATE UNIQUE INDEX "app"."t_ab" ON "t" ("a", "b")"#
        );
        let drop_index = || C::DropIndex {
            name: "t_ab".into(),
        };
        assert_eq!(
            sql(MYSQL, drop_index()).unwrap(),
            "DROP INDEX `t_ab` ON `app`.`t`"
        );
        assert_eq!(
            sql(Dialect::Postgres, drop_index()).unwrap(),
            r#"DROP INDEX "app"."t_ab""#
        );

        // tables, index names and constraints
        let rename_table = || C::RenameTable {
            new_name: "u".into(),
        };
        assert_eq!(
            sql(Dialect::Postgres, rename_table()).unwrap(),
            r#"ALTER TABLE "app"."t" RENAME TO "u""#
        );
        assert_eq!(
            sql(MYSQL, rename_table()).unwrap(),
            "ALTER TABLE `app`.`t` RENAME TO `app`.`u`"
        );
        assert_eq!(
            sql(Dialect::Sqlite, C::DropTable).unwrap(),
            r#"DROP TABLE "app"."t""#
        );
        let rename_index = || C::RenameIndex {
            name: "i".into(),
            new_name: "j".into(),
        };
        assert_eq!(
            sql(Dialect::Postgres, rename_index()).unwrap(),
            r#"ALTER INDEX "app"."i" RENAME TO "j""#
        );
        assert_eq!(
            sql(MYSQL, rename_index()).unwrap(),
            "ALTER TABLE `app`.`t` RENAME INDEX `i` TO `j`"
        );
        let constraint = |constraint: Constraint| C::AddConstraint {
            name: "c".into(),
            constraint,
        };
        let foreign_key = || {
            constraint(Constraint::ForeignKey {
                columns: vec!["team_id".into()],
                referenced_table: "teams".into(),
                referenced_columns: vec!["id".into()],
                on_delete: Some(ReferentialAction::SetNull),
            })
        };
        assert_eq!(
            sql(Dialect::Postgres, foreign_key()).unwrap(),
            r#"ALTER TABLE "app"."t" ADD CONSTRAINT "c" FOREIGN KEY ("team_id") REFERENCES "app"."teams" ("id") ON DELETE SET NULL"#
        );
        assert_eq!(
            sql(
                MYSQL,
                constraint(Constraint::Check {
                    expression: "price >= 0".into()
                })
            )
            .unwrap(),
            "ALTER TABLE `app`.`t` ADD CONSTRAINT `c` CHECK (price >= 0)"
        );
        assert_eq!(
            sql(
                Dialect::Postgres,
                constraint(Constraint::Unique {
                    columns: vec!["a".into(), "b".into()]
                })
            )
            .unwrap(),
            r#"ALTER TABLE "app"."t" ADD CONSTRAINT "c" UNIQUE ("a", "b")"#
        );
        assert_eq!(
            sql(MYSQL, C::DropConstraint { name: "c".into() }).unwrap(),
            "ALTER TABLE `app`.`t` DROP CONSTRAINT `c`"
        );

        // what an engine cannot do is said, not rewritten
        let refused = |dialect: Dialect, change: C| match sql(dialect, change) {
            Err(AppError::Validation(message)) => message,
            other => panic!("expected a refusal: {other:?}"),
        };
        assert!(refused(Dialect::Sqlite, set_type()).contains("sem recriar a tabela"));
        assert!(refused(Dialect::Sqlite, default(Some("1"))).contains("sem recriar a tabela"));
        assert!(refused(Dialect::Sqlite, nullable(true)).contains("sem recriar a tabela"));
        assert!(refused(MYSQL, set_type()).contains("MODIFY COLUMN"));
        assert!(refused(MYSQL, nullable(true)).contains("MODIFY COLUMN"));
        assert!(refused(Dialect::Postgres, redefine()).contains("só do MySQL"));
        assert!(refused(Dialect::Sqlite, rename_index()).contains("não renomeia índices"));
        assert!(refused(Dialect::Sqlite, foreign_key()).contains("recriar a tabela"));
        assert!(
            refused(Dialect::Sqlite, C::DropConstraint { name: "c".into() })
                .contains("recriar a tabela")
        );
        assert_eq!(
            refused(
                Dialect::Postgres,
                constraint(Constraint::ForeignKey {
                    columns: vec!["a".into(), "b".into()],
                    referenced_table: "u".into(),
                    referenced_columns: vec!["id".into()],
                    on_delete: None,
                })
            ),
            "a chave estrangeira liga o mesmo número de colunas dos dois lados"
        );
        // nor can a typed `;` smuggle in a second command
        assert!(
            refused(
                Dialect::Postgres,
                C::AddColumn {
                    column: column("c", "int; DROP TABLE users", true, None)
                }
            )
            .contains("mais de um comando")
        );
        assert_eq!(
            refused(
                Dialect::Postgres,
                C::CreateTable {
                    columns: vec![column("a", "int", true, None)],
                    primary_key: vec!["id".into()]
                }
            ),
            "a chave primária usa id, que não é uma coluna da tabela"
        );
        assert_eq!(
            refused(
                Dialect::Postgres,
                C::AddColumn {
                    column: column("c", " ", true, None)
                }
            ),
            "informe o tipo de c"
        );
    }

    #[test]
    fn plain_page_orders_by_primary_key() {
        let pk = ["id".to_string(), "tenant".to_string()];
        assert_eq!(
            browse_sql(Dialect::Postgres, &request(), &pk).unwrap(),
            r#"SELECT * FROM "public"."users" ORDER BY "id", "tenant" LIMIT 101 OFFSET 0"#
        );
        assert_eq!(
            browse_sql(MYSQL, &request(), &pk).unwrap(),
            "SELECT * FROM `public`.`users` ORDER BY `id`, `tenant` LIMIT 101 OFFSET 0"
        );
        assert_eq!(
            browse_sql(Dialect::Sqlite, &request(), &[]).unwrap(),
            r#"SELECT * FROM "public"."users" LIMIT 101 OFFSET 0"#
        );
    }

    #[test]
    fn filters_sort_and_page() {
        let mut req = request();
        req.page = 3;
        req.page_size = 50;
        req.sort = Some(Sort {
            column: "name".into(),
            direction: SortDirection::Desc,
        });
        req.filters = vec![
            Filter {
                column: "email".into(),
                op: FilterOp::Like,
                value: Some("%@x.com".into()),
            },
            Filter {
                column: "age".into(),
                op: FilterOp::Eq,
                value: Some("30".into()),
            },
            Filter {
                column: "deleted_at".into(),
                op: FilterOp::IsNull,
                value: Some("ignored".into()),
            },
            Filter {
                column: "verified_at".into(),
                op: FilterOp::IsNotNull,
                value: None,
            },
            Filter {
                column: "created_at".into(),
                op: FilterOp::Gte,
                value: Some("2026-01-01".into()),
            },
            Filter {
                column: "id".into(),
                op: FilterOp::In,
                value: Some("1, 2,,3 ".into()),
            },
            Filter {
                column: "role".into(),
                op: FilterOp::Ne,
                value: Some("it's".into()),
            },
        ];

        assert_eq!(
            browse_sql(Dialect::Postgres, &req, &["id".into()]).unwrap(),
            concat!(
                r#"SELECT * FROM "public"."users" WHERE "email"::text LIKE '%@x.com' AND "age" = '30' "#,
                r#"AND "deleted_at" IS NULL AND "verified_at" IS NOT NULL "#,
                r#"AND "created_at" >= '2026-01-01' AND "id" IN ('1', '2', '3') AND "role" <> 'it''s' "#,
                r#"ORDER BY "name" DESC LIMIT 51 OFFSET 150"#
            )
        );
        assert!(
            browse_sql(MYSQL, &req, &[])
                .unwrap()
                .contains("WHERE CAST(`email` AS CHAR) LIKE '%@x.com'")
        );
    }

    #[test]
    fn copies_rows_as_inserts_with_exact_text() {
        let columns = vec!["id".to_string(), "name".to_string(), "score".to_string()];
        let rows = vec![
            vec![
                Cell::Int("9007199254740993".into()),
                Cell::Text(r"O'Brien c:\temp".into()),
                Cell::Float(0.1),
            ],
            vec![Cell::Int("2".into()), Cell::Null, Cell::Bool(true)],
        ];

        assert_eq!(
            insert_sql(Dialect::Postgres, "app", "users", &columns, &rows).unwrap(),
            "INSERT INTO \"app\".\"users\" (\"id\", \"name\", \"score\") \
             VALUES ('9007199254740993', E'O''Brien c:\\\\temp', '0.1');\n\
             INSERT INTO \"app\".\"users\" (\"id\", \"name\", \"score\") \
             VALUES ('2', NULL, 'true');\n"
        );
        assert_eq!(
            insert_sql(MYSQL, "app", "users", &columns, &rows[1..]).unwrap(),
            "INSERT INTO `app`.`users` (`id`, `name`, `score`) VALUES ('2', NULL, 'true');\n"
        );

        let partial = vec![vec![
            Cell::Int("1".into()),
            Cell::Bytes {
                len: 64,
                preview_hex: "00".into(),
            },
            Cell::Null,
        ]];
        let error = insert_sql(Dialect::Sqlite, "main", "t", &columns, &partial).unwrap_err();
        assert!(error.to_string().contains("a coluna name"), "{error}");
        assert!(insert_sql(Dialect::Sqlite, "main", "t", &columns, &[vec![Cell::Null]]).is_err());
    }

    #[test]
    fn builds_changes_per_dialect() {
        let update = RowChange::Update {
            key: vec![
                key("id", Cell::Int("7".into())),
                key("tenant", Cell::Text("a'b".into())),
            ],
            values: vec![value("name", Some("O'Brien")), value("note", None)],
        };
        let insert = RowChange::Insert {
            values: vec![value("name", Some(r"c:\temp")), value("age", None)],
        };
        let empty_insert = RowChange::Insert { values: vec![] };
        let delete = RowChange::Delete {
            key: vec![key("id", Cell::Int("9".into()))],
        };

        assert_eq!(
            change_sql(Dialect::Postgres, "app", "users", &update).unwrap(),
            r#"UPDATE "app"."users" SET "name" = 'O''Brien', "note" = NULL WHERE "id" = '7' AND "tenant" = 'a''b'"#
        );
        assert_eq!(
            change_sql(Dialect::Postgres, "app", "users", &insert).unwrap(),
            r#"INSERT INTO "app"."users" ("name", "age") VALUES (E'c:\\temp', NULL)"#
        );
        assert_eq!(
            change_sql(MYSQL, "app", "users", &insert).unwrap(),
            r"INSERT INTO `app`.`users` (`name`, `age`) VALUES ('c:\\temp', NULL)"
        );
        assert_eq!(
            change_sql(Dialect::Sqlite, "main", "users", &insert).unwrap(),
            r#"INSERT INTO "main"."users" ("name", "age") VALUES ('c:\temp', NULL)"#
        );
        assert_eq!(
            change_sql(Dialect::Postgres, "app", "users", &empty_insert).unwrap(),
            r#"INSERT INTO "app"."users" DEFAULT VALUES"#
        );
        assert_eq!(
            change_sql(MYSQL, "app", "users", &empty_insert).unwrap(),
            "INSERT INTO `app`.`users` () VALUES ()"
        );
        assert_eq!(
            change_sql(MYSQL, "app", "users", &delete).unwrap(),
            "DELETE FROM `app`.`users` WHERE `id` = '9'"
        );
    }

    #[test]
    fn key_text_uses_the_rendered_value() {
        let cases = [
            (Cell::Bool(true), "true"),
            (Cell::Float(0.1), "0.1"),
            (Cell::Decimal("1.50".into()), "1.50"),
            (Cell::Date("2024-02-29".into()), "2024-02-29"),
            (
                Cell::Timestamp {
                    value: "2024-01-01 13:00:00+00".into(),
                    tz: Some("UTC".into()),
                },
                "2024-01-01 13:00:00+00",
            ),
            (Cell::Json(r#"{"a": 1}"#.into()), r#"{"a": 1}"#),
        ];
        for (cell, expected) in cases {
            assert_eq!(key_text(&cell).unwrap(), expected);
        }
    }

    #[test]
    fn rejects_unusable_changes() {
        let bytes = Cell::Bytes {
            len: 1,
            preview_hex: "00".into(),
        };
        let changes = [
            RowChange::Delete { key: vec![] },
            RowChange::Delete {
                key: vec![key("id", Cell::Null)],
            },
            RowChange::Delete {
                key: vec![key("id", bytes)],
            },
            RowChange::Update {
                key: vec![key("id", Cell::Int("1".into()))],
                values: vec![],
            },
        ];
        for change in changes {
            assert!(matches!(
                change_sql(Dialect::Postgres, "s", "t", &change),
                Err(AppError::Validation(_))
            ));
        }
    }
}
